// Lê o aviso do Evolution API e descarta o que não é conversa com uma pessoa.
const esperado = $env.WEBHOOK_TOKEN;
const saida = [];
for (const item of $input.all()) {
  const headers = item.json.headers || {};
  if (!esperado || headers['x-webhook-token'] !== esperado) continue; // não veio do nosso Evolution
  const b = item.json.body || {};
  if (b.event !== 'messages.upsert') continue;
  const d = Array.isArray(b.data) ? b.data[0] : b.data;
  const k = (d && d.key) || {};
  let jid = k.remoteJid || '';
  if (jid.endsWith('@lid')) jid = k.remoteJidAlt || k.senderPn || '';
  if (!jid.endsWith('@s.whatsapp.net')) continue; // grupos, status e canais
  const m = d.message || {};
  const texto = m.conversation || (m.extendedTextMessage && m.extendedTextMessage.text)
    || (m.imageMessage && m.imageMessage.caption) || (m.videoMessage && m.videoMessage.caption)
    || '[' + (d.messageType || 'mensagem') + ']';
  // de_mim: enviada pelo WhatsApp da agência (o ERP usa para o robô sair da conversa).
  saida.push({ json: { instancia: b.instance, numero: jid.split('@')[0], nome: k.fromMe ? '' : (d.pushName || ''),
    mensagem: texto, de_mim: Boolean(k.fromMe) } });
}
return saida;

// O ERP decide o que responder (menu, perguntas do orçamento...). Sem resposta, não manda nada.
const contatos = $('Ler mensagem').all();
return $input.all().map((item, i) => ({ item, contato: contatos[i].json }))
  .filter(({ item }) => typeof item.json.resposta === 'string' && item.json.resposta.trim())
  .map(({ item, contato }) => ({ json: { instancia: contato.instancia, numero: contato.numero, texto: item.json.resposta } }));
